"""Build cr/<page>.js from the rubric and run the accuracy test.  usage: python3 src/cr/build.py <repo> [g11]"""
import json, os, subprocess, sys, importlib
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
REPO = sys.argv[1]; G = sys.argv[2] if len(sys.argv) > 2 else 'g11'
rub = importlib.import_module('%s_rubric' % G).R
cases = importlib.import_module('%s_cases' % G).C
page = '%s-advanced.html' % G
os.makedirs(os.path.join(REPO, 'cr'), exist_ok=True)
open(os.path.join(REPO, 'cr', page.replace('.html', '.js')), 'w', encoding='utf-8').write(
    '/* generated by src/cr/build.py — rubric for constructed-response items */\nwindow.SSH_CR=' + json.dumps({'page': page, 'tests': rub}, ensure_ascii=False, separators=(',', ':')) + ';\n')
s = open(os.path.join(REPO, page), encoding='utf-8').read(); i = s.find('const DATA=') + 11
D = json.JSONDecoder().raw_decode(s[i:])[0]
items = {str(T['n']): {'rw%d' % k: q for k, q in enumerate(T['q10'])} for T in D}
json.dump({'rub': rub, 'cases': {str(k): v for k, v in cases.items()}, 'items': items}, open('/tmp/cr_in.json', 'w'), ensure_ascii=False)
js = r'''
const CR=require(process.argv[2]);const X=require('/tmp/cr_in.json');
let n=0,agree=0,fpos=0,fneg=0,rev=0,revWant=0,rows=[],byKind={};
for(const t in X.cases){for(const id in X.cases[t]){for(const [ans,exp] of X.cases[t][id]){
  const rub=X.rub[t][id]||{};let r;
  if(id.startsWith('rw')) r=CR.rewrite(ans,X.items[t][id],rub);
  else if(id==='q5'||id==='q6') r=CR.reading2(ans[0],ans[1],{ideas:rub.ideas});
  else r=CR.reading1(ans,{ideas:rub.ideas});
  const want=Array.isArray(exp)?exp[0]:exp, wantPts=Array.isArray(exp)?exp[1]:null;
  const kind=id.startsWith('rw')?'grammar':'reading';byKind[kind]=byKind[kind]||{n:0,agree:0,danger:0,review:0};
  n++;byKind[kind].n++;
  const same=r.state===want&&(wantPts===null||r.got===wantPts);
  if(same){agree++;byKind[kind].agree++}
  if(r.state==='review'){rev++;byKind[kind].review++}
  // dangerous: confident decision that contradicts the teacher
  const danger=(r.state==='ok'&&want==='no')||(r.state==='no'&&want==='ok')||(r.state!=='review'&&wantPts!==null&&r.got>wantPts);
  if(danger){byKind[kind].danger++; if(r.state==='ok')fpos++; else fneg++}
  if(!same) rows.push([danger?'DANGER':'diff',t,id,JSON.stringify(ans).slice(0,90),'want',JSON.stringify(exp),'got',r.state,r.got]);
}}}
console.log(JSON.stringify({n,agree,review:rev,falsePositive:fpos,falseNegative:fneg,byKind}));
rows.forEach(r=>console.log(r.join(' | ')));
'''
open('/tmp/cr_run.js', 'w').write(js)
out = subprocess.run(['node', '/tmp/cr_run.js', os.path.abspath(os.path.join(REPO, 'ssh-cr.js'))], capture_output=True, text=True)
print(out.stdout[-12000:], out.stderr[-3000:])
